```go
if x+idx == len(b.set)-1 {
    // Last word: only consider bits up to b.length-1
    wordStartBit := uint(x+idx) * wordSize
    if wordStartBit < b.length {
        lastWordRelevantBits := b.length - wordStartBit
        if lastWordRelevantBits > 0 && lastWordRelevantBits < wordSize {
            // Mask out the irrelevant high bits by setting them to 1
            mask := allBits << lastWordRelevantBits
            maskedWord := word | mask
            if maskedWord != allBits {
                index = uint((x+idx)*wordSize + bits.TrailingZeros64(^maskedWord))
            } else {
                continue // No clear bits in the relevant part of last word
            }
        } else if lastWordRelevantBits >= wordSize {
            // All bits in this word are relevant
            index = uint((x+idx)*wordSize + bits.TrailingZeros64(^word))
        } else {
            continue // No relevant bits
        }
    } else {
        continue // This word starts beyond the bitset length
    }
} else {
    index = uint((x+idx)*wordSize + bits.TrailingZeros64(^word))
}
